Here is the commit message:
media: as102: fix to not free memory after the device is
 registered in as102_usb_probe()

In as102_usb driver, the following race condition occurs:
```
		CPU0						CPU1
as102_usb_probe()
  kzalloc(); // alloc as102_dev_t
  ....
  usb_register_dev();
						fd = sys_open("/path/to/dev"); // open as102 fd
						....
  usb_deregister_dev();
  ....
  kfree(); // free as102_dev_t
  ....
						sys_close(fd);
						  as102_release() // UAF!!
						    as102_usb_release()
						      kfree(); // DFB!!
```

When a USB character device registered with usb_register_dev() is later
unregistered (via usb_deregister_dev() or disconnect), the device node is
removed so new open() calls fail. However, file descriptors that are
already open do not go away immediately: they remain valid until the last
reference is dropped and the driver's .release() is invoked.

In as102, as102_usb_probe() calls usb_register_dev() and then, on an
error path, does usb_deregister_dev() and frees as102_dev_t right away.
If userspace raced a successful open() before the deregistration, that
open FD will later hit as102_release() --> as102_usb_release() and access
or free as102_dev_t again, occur a race to use-after-free and
double-free vuln.

The fix is to never kfree(as102_dev_t) directly once usb_register_dev()
has succeeded. After deregistration, defer freeing memory to .release().

In other words, let release() perform the last kfree when the final open
FD is closed.

Cc: <stable@vger.kernel.org>
Reported-by: syzbot+47321e8fd5a4c84088db@syzkaller.appspotmail.com
Closes: https://syzkaller.appspot.com/bug?extid=47321e8fd5a4c84088db
Fixes: cd19f7d3e39b ("[media] as102: fix leaks at failure paths in as102_usb_probe()")
Signed-off-by: Jeongjun Park <aha310510@gmail.com>
Signed-off-by: Hans Verkuil <hverkuil+cisco@kernel.org>

Here is the root cause:
In as102_usb_probe(), after successfully registering the device with usb_register_dev(), if an error occurs later, the driver frees the device structure (as102_dev_t) immediately after usb_deregister_dev(), ignoring that existing open file descriptors may still reference the device. This leads to use-after-free and double-free when those file descriptors are closed and the release() callback accesses the freed memory.

Here is the patch:

 static int as102_usb_probe(struct usb_interface *intf,
 			   const struct usb_device_id *id)
 {
 	int ret;
 	struct as102_dev_t *as102_dev;
 	int i;

 	/* This should never actually happen */
 	if (ARRAY_SIZE(as102_usb_id_table) !=
 	    (sizeof(as102_device_names) / sizeof(const char *))) {
 		pr_err("Device names table invalid size");
 		return -EINVAL;
 	}

 	as102_dev = kzalloc_obj(struct as102_dev_t);
 	if (as102_dev == NULL)
 		return -ENOMEM;

 	/* Assign the user-friendly device name */
 	for (i = 0; i < ARRAY_SIZE(as102_usb_id_table); i++) {
 		if (id == &as102_usb_id_table[i]) {
 			as102_dev->name = as102_device_names[i];
 			as102_dev->elna_cfg = as102_elna_cfg[i];
 		}
 	}

 	if (as102_dev->name == NULL)
 		as102_dev->name = "Unknown AS102 device";

 	/* set private callback functions */
 	as102_dev->bus_adap.ops = &as102_priv_ops;

 	/* init cmd token for usb bus */
 	as102_dev->bus_adap.cmd = &as102_dev->bus_adap.token.usb.c;
 	as102_dev->bus_adap.rsp = &as102_dev->bus_adap.token.usb.r;

 	/* init kernel device reference */
 	kref_init(&as102_dev->kref);

 	/* store as102 device to usb_device private data */
 	usb_set_intfdata(intf, (void *) as102_dev);

 	/* store in as102 device the usb_device pointer */
 	as102_dev->bus_adap.usb_dev = usb_get_dev(interface_to_usbdev(intf));

 	/* we can register the device now, as it is ready */
 	ret = usb_register_dev(intf, &as102_usb_class_driver);
 	if (ret < 0) {
 		/* something prevented us from registering this driver */
 		dev_err(&intf->dev,
 			"%s: usb_register_dev() failed (errno = %d)\n",
 			__func__, ret);
 		goto failed;
 	}

 	pr_info("%s: device has been detected\n", DRIVER_NAME);

 	/* request buffer allocation for streaming */
 	ret = as102_alloc_usb_stream_buffer(as102_dev);
 	if (ret != 0)
 		goto failed_stream;

 	/* register dvb layer */
 	ret = as102_dvb_register(as102_dev);
 	if (ret != 0)
 		goto failed_dvb;

 	return ret;

 failed_dvb:
 	as102_free_usb_stream_buffer(as102_dev);
 failed_stream:
+	usb_set_intfdata(intf, NULL);
 	usb_deregister_dev(intf, &as102_usb_class_driver);
+	return ret;
 failed:
 	usb_put_dev(as102_dev->bus_adap.usb_dev);
 	usb_set_intfdata(intf, NULL);
 	kfree(as102_dev);
 	return ret;
 }



